+                StyleAttributeMap.Builder b = StyleAttributeMap.builder();
+                for (StyleAttribute a : as) {
+                    if (supported.contains(a)) {
+                        b.set(a, map.get(a));
+                    }
+                }
+                return b.build();
+            }
+        }
+        return map;
+    }
